create table if not exists categories(id bigint generated always as identity primary key,name text not null,slug text unique,icon text default '👜',created_at timestamptz default now());
create table if not exists products(id bigint generated always as identity primary key,category_id bigint references categories(id),name text not null,price numeric default 0,old_price numeric,stock integer default 0,description text,colors jsonb default '[]',images jsonb default '[]',material text,size text,dimensions text,features jsonb default '[]',is_active boolean default true,created_at timestamptz default now());
create table if not exists orders(id bigint generated always as identity primary key,customer_name text not null,phone text not null,wilaya text,commune text,address text,status text default 'جديد',total numeric default 0,created_at timestamptz default now());
create table if not exists shipping_rates(id bigint generated always as identity primary key,wilaya text unique,home_price numeric,desk_price numeric,active boolean default true);
